<script setup lang="ts">
import { ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { api,statusMeta,type Case } from '../../api'
const items=ref<Case[]>([])
onShow(load)
async function load(){try{items.value=await api.cases()}catch(e){uni.showToast({title:e instanceof Error?e.message:'加载失败',icon:'none'})}}
function create(){uni.navigateTo({url:'/pages/cases/create'})}
function detail(item:Case){uni.showModal({title:item.caseNo,content:`${item.summary}\n\n法律依据：${item.legalBasis}\n当前阶段：${statusMeta(item.status).label}`,showCancel:false})}
</script>
<template><view class="page pad"><view class="between"><view><text class="page-title">案件办理</text><text class="tiny">已承办案件与执法流程</text></view><button class="btn btn-sm btn-primary" @click="create">＋立案</button></view><view class="summary"><view><b>{{items.filter(i=>i.status!=='closed').length}}</b><text>在办案件</text></view><view><b>{{items.filter(i=>i.status==='evidence').length}}</b><text>取证阶段</text></view><view><b>{{items.filter(i=>i.status==='closed').length}}</b><text>已结案</text></view></view><view class="case-list"><view class="case" v-for="item in items" :key="item.id" @click="detail(item)"><view class="between"><view><text class="strong">{{item.subjectName}}</text><text class="tiny">{{item.caseNo}} · {{item.caseType}}</text></view><text class="tag" :class="statusMeta(item.status).tone">{{statusMeta(item.status).label}}</text></view><text class="muted">{{item.summary}}</text><view class="progress"><view :style="{width:`${item.progress}%`}"/></view><view class="between"><text class="tiny">承办：{{item.handler}} · {{item.filedAt}}</text><text class="link">案件详情 ›</text></view></view></view></view></template>
<style lang="scss" scoped>.page-title{display:block;font-size:38rpx;font-weight:750}.summary{display:grid;grid-template-columns:repeat(3,1fr);margin:20rpx 0;padding:20rpx;border-radius:20rpx;background:#fff}.summary view{display:flex;align-items:center;flex-direction:column;gap:4rpx;border-right:1rpx solid #edf2ee}.summary view:last-child{border-right:0}.summary b{color:#0e5233;font-family:monospace;font-size:32rpx}.summary text{color:#718277;font-size:19rpx}.case{margin-bottom:14rpx;padding:20rpx;border:1rpx solid #e1e9e3;border-radius:20rpx;background:#fff}.case>view:first-child>view{display:flex;flex-direction:column;gap:4rpx}.case>.muted{display:block;margin:10rpx 0}.case .progress{margin:12rpx 0}.link{color:#12764a;font-size:19rpx}</style>
